 50      public static Simple_fcn inferAndInstantiateGenericFunction(List<FValue> args,
 51                                                                  GenericFunctionOrMethod appliedThing,
 52                                                                  Environment envForInference) throws ProgramError {
 53  
 54          if (DUMP_INFERENCE) System.err.println("IAIGF " + appliedThing + " with " + args);
 55  
 56          GenericTypeInstance selfType = null; // initialized if generic functional method
 57  
 58          if (appliedThing instanceof GenericFunctionalMethod) {
 59              GenericFunctionalMethod gfm = (GenericFunctionalMethod) appliedThing;
 60              int spi = gfm.getSelfParameterIndex();
 61              FTypeGeneric declaredSelfType = gfm.getSelfParameterTypeAsGeneric();
 62              FValue selfArg = args.get(spi);
 63  
 64              if (selfArg.type() instanceof GenericTypeInstance) {
 65                  selfType = (GenericTypeInstance) selfArg.type();
 66                  // Find the supertype that exactly matches "self"
 67                  for (FType ft : selfType.getTransitiveExtends()) {
 68                      if (ft instanceof GenericTypeInstance && ((GenericTypeInstance) ft).getGeneric().equals(
 69                              declaredSelfType)) {
 70                          selfType = (GenericTypeInstance) ft;
 71                          break;
 72                      }
 73                  }
 74                  envForInference = selfType.getWithin();
 75              } else return error(errorMsg("Non-generic-instance type for self argument ",
 76                                           selfArg,
 77                                           " to generic functional method ",
 78                                           appliedThing));
 79          }
 80  
 81          List<StaticParam> tparams = appliedThing.getStaticParams();
 82          List<Param> params = appliedThing.getParams();
 83          // Must use the right environment for unifying against the generic.
 84          // It was "e", which is wrong.
 85          EvalType et = new EvalType(appliedThing.getWithin());// e);
 86          // The types of the actual parameters ought to unify with the
 87          // types of the formal parameters.
 88          BoundingMap<String, FType, TypeLatticeOps> abm = new
 89                  // ABoundingMap
 90                  LatticeIntervalMap<String, FType, TypeLatticeOps>(TypeLatticeOps.V, DefaultComparator.V);
 91          Param p = null;
 92          Set<String> tp_set = new HashSet<String>();
 93          List<StaticParam> rechecks = null;
 94          for (StaticParam sp : tparams) {
 95              boolean rechecked = false;
 96              String name = NodeUtil.getName(sp);
 97              tp_set.add(name);
 98              if (NodeUtil.isTypeParam(sp)) {
 99                  if (DUMP_INFERENCE) System.err.println("TypeParam " + sp);
100                  for (Type tr : sp.getExtendsClause()) {
101                      // Preinstall bounds in the boundingmap
102                      try {
103                          FType tt = et.evalType(tr);
104                          if (DUMP_INFERENCE) System.err.println("    extends " + tr + " = " + tt);
105                          abm.meetPut(name, tt);
106                      }
107                      catch (FortressException pe) {
108                          if (DUMP_INFERENCE) System.err.println("    extends with failed evalType " + tr);
109                          if (!rechecked) {
110                              rechecked = true;
111                              if (rechecks == null) {
112                                  rechecks = new ArrayList<StaticParam>();
113                              }
114                              rechecks.add(sp);
115                          }
116                      }
117                  }
118              } else if (DUMP_INFERENCE) System.err.println("Non-simple StaticParam " + sp);
119          }
120          /* FIX FOR #62 */
121          if (params.size() == 1 && args.size() != 1) {
122              Iterator<Param> pit = params.iterator();
123              Param pa = pit.next();
124  
125              if (!NodeUtil.isVarargsParam(pa)) {
126                  /* Tuple (or even re-tuple) arguments when inferring type
127                   * if passing different # of args to 1-arg function. */
128                  if (DUMP_INFERENCE) {
129                      System.err.println("Tupling args to match single-arg context.");
130                  }
131                  args = Useful.<FValue>list(FTuple.make(args));
132              }
133          }
134          Iterator<Param> pit = params.iterator();
135          for (FValue a : args) {
136              FType at = a.type();
137              if (at == null) {
138                  if (DUMP_INFERENCE) System.err.println("Argument " + a + " without type info.");
139                  return error(errorMsg("Argument ", a, " has no type information"));
140              }
141              if (pit.hasNext()) {
142                  p = pit.next();
143              } else if (p == null) {
144                  if (DUMP_INFERENCE) System.err.println("Arguments " + args + " to 0-arg function.");
145                  error(errorMsg(" Arguments ", args, " given to 0-argument generic function ", appliedThing));
146              }
147              try {
148                  if (!NodeUtil.isVarargsParam(p)) {
149                      Option<TypeOrPattern> t = p.getIdType();
150                      // why can't we just skip if missing?
151                      if (t.isNone()) {
152                          /*
153                           * Fake the type for a generic functional method
154                           * invocation.
155                           */
156                          if (p.getName().toString().equals("self") && appliedThing instanceof GenericFunctionalMethod) {
157                              // Use precomputed selfType that will match declared
158                              GenericTypeInstance gi = (GenericTypeInstance) selfType;
159  
160                              at.unify(envForInference,
161                                       tp_set,
162                                       abm,
163                                       gi.getGeneric().getInstantiationForFunctionalMethodInference());// instantiationAST());
164                          } else {
165                              if (DUMP_INFERENCE) System.err.println("Parameter lacks type.");
166                              error("Parameter needs type for generic resolution");
167                          }
168                      } else {
169                          Type ty = NodeUtil.optTypeOrPatternToType(t).unwrap();
170                          if (DUMP_INFERENCE) System.err.println("Unifying " + at + " and " + ty);
171                          at.unify(envForInference, tp_set, abm, ty);
172                      }
173                  } else { // a varargs param
174                      Type ty = p.getVarargsType().unwrap();
175                      if (DUMP_INFERENCE) System.err.println("Unifying " + at + " and vararg type " + ty);
176                      at.unify(envForInference, tp_set, abm, ty);
177                  }
178              }
179              catch (FortressException ex) {
180                  /* Give decent feedback when unification fails. */
181                  throw ex.setWithin(envForInference);
182              }
183          }
184  
185          if (DUMP_INFERENCE) System.err.println("ABM 0={" + abm + "}");
186  
187          /*
188           * Filter the inference through the result type, making it more specific
189           * (which is less-specific, for arrow domain types).
190           */
191          MakeInferenceSpecific mis = new MakeInferenceSpecific(abm);
192  
193          // TODO: There is still a lurking error in inference, probably in arrow
194          // types.
195  
196          // for (Param param : params) {
197          // Option<Type> t = param.getType();
198          // t.getVal().accept(mis);
199          // }
200          // if (DUMP_INFERENCE)
201          // System.err.println("ABM 1={" + abm + "}");
202  
203          Option<Type> opt_rt = appliedThing.getReturnType();
204  
205          if (opt_rt.isSome()) opt_rt.unwrap().accept(mis);
206  
207          if (DUMP_INFERENCE) System.err.println("ABM 2={" + abm + "}");
208  
209          /* Enforce upper bounds that we could not enforce up front.
210           * We're worried here about self-typing idioms.  What we have to do
211           * is find the (unique) occurrence of the type stem of the bounding type
212           * in the supertypes of the bounded type.
213           *
214           * What do we do with variable upper bounds?  We should impose the bounds
215           * derived for the given type variable.
216           */
217          if (rechecks != null) {
218              for (StaticParam tp : rechecks) {
219                  FType t = abm.get(NodeUtil.getName(tp));
220                  if (t == null) {
221                      if (DUMP_INFERENCE) {
222                          System.err.println(
223                                  "Can't constrain the type " + tp + "\n    enough to enforce its upper bounds " +
224                                  tp.getExtendsClause() + "\n    Choosing to erase to bottom.");
225                      }
226                      t = BottomType.ONLY;
227                  }
228                  for (Type tr : tp.getExtendsClause()) {
229                      if (DUMP_INFERENCE) {
230                          System.err.println("Unifying " + tp + " lower bound " + t + "\n    with its bound " + tr + " " +
231                                             tr.getClass());
232                      }
233                      t.unify(envForInference, tp_set, abm, tr);
234                  }
235              }
236          }
237  
238          /*
239           * Iterate over static parameters, choosing least-general binding for
240           * each one.
241           */
242          ArrayList<FType> tl = new ArrayList<FType>(tparams.size());
243          for (StaticParam tp : tparams) {
244              FType t = abm.get(NodeUtil.getName(tp));
245              if (t == null) t = BottomType.ONLY;
246              tl.add(t);
247          }
248          Simple_fcn sfcn = appliedThing.typeApply(tl);
249          if (DUMP_INFERENCE) System.err.println("Result " + sfcn);
250          return sfcn;
251      }

