D=/home/user/fortress-walkinfer/explorations/compile-ladder/rung-inference-walk; cat > $D/condense.awk <<'EOF'
# condense.awk: walk-run.sh's output with each program's printed lines, the first two lines of an error
# (its class and message) and the exit code; the context lines, the launcher's hint and the scratch paths dropped.
/^# walk-run/ { print; next }
/^== / { print; err = 0; next }
/^rc=/ { print "   " $0; next }
/^com.sun.fortress.exceptions/ { err = 2; sub(/^com.sun.fortress.exceptions./, ""); print "   ! " $0; next }
err > 0 { err--; if ($0 !~ /^Context:/) print "   ! " $0; next }
/^(Context:|toplevel:|Turn on|java.lang.Throwable|tmp\/walk-run)/ { next }
NF { print "   " $0 }
EOF
cat > $D/oneshape-run.sh <<'EOF'
#!/bin/bash
# oneshape-run.sh <label>: Fable's one-shape walk programs (explorations/reviews/numerics-plan-fable/probes/
# one-shape/walk/*.fss, the cases OneShapeW.fss gathers), each under walk by walk-run.sh, one JVM at a time
# with a private cache; WALK_HOME passes through (the base home). Writes probes/oneshape-<label>.txt.
set -u
FH=${FORTRESS_HOME:?}
D="$FH/explorations/compile-ladder/rung-inference-walk"
"$D/walk-run.sh" $(ls "$FH"/explorations/reviews/numerics-plan-fable/probes/one-shape/walk/*.fss) \
  | awk -f "$D/condense.awk" | sed "s#tmp/walk-run/[A-Za-z0-9]*/##g" > "$D/probes/oneshape-${1:?label}.txt"
cat "$D/probes/oneshape-$1.txt"
EOF
chmod +x $D/oneshape-run.sh; echo ok

